# name: more_distinct_triplets_at_equal_switches
# description: Among pairs with equal switch counts but different numbers of distinct length-3 substrings, the rate of choosing the sequence with more distinct triplets (richer local patterns); observed above null means people reward local pattern variety that the alternation/periodicity/balance terms miss.
def test_statistic(df):
    a = df["sequence_a"].to_numpy(); b = df["sequence_b"].to_numpy()
    u = pd.unique(np.concatenate([a, b]))
    tri = {s: len({s[i:i + 3] for i in range(max(len(s) - 2, 0))}) for s in u}
    sw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in u}
    ta = df["sequence_a"].map(tri).to_numpy(); tb = df["sequence_b"].map(tri).to_numpy()
    swa = df["sequence_a"].map(sw).to_numpy(); swb = df["sequence_b"].map(sw).to_numpy()
    m = (swa == swb) & (ta != tb)
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.where(ta[m] > tb[m], c, 1 - c).mean())

# name: participant_side_bias_variance
# description: Variance across participants of their left-choice rate; observed above null means individuals have stable left/right response biases the model (no side bias) does not produce.
def test_statistic(df):
    return float(df.groupby("participant_id")["chose_left"].mean().var())

# name: pair_consensus_extremity_long
# description: Mean over length-8 pairs of |proportion choosing left - 0.5|; observed above null means people agree on long-sequence pairs more strongly than the model predicts (model too noisy/under-confident there), below null means the model is over-confident.
def test_statistic(df):
    m = (df["sequence_a"].str.len() == 8).to_numpy()
    sub = df.loc[m]
    if len(sub) == 0:
        return 0.0
    key = sub["sequence_a"] + "|" + sub["sequence_b"]
    p = sub.groupby(key)["chose_left"].mean()
    return float((p - 0.5).abs().mean())

# name: symmetric_sequence_avoidance
# description: Among pairs where exactly one sequence is mirror-symmetric (a palindrome or its H/T-complemented reversal), the rate of choosing the asymmetric one; observed above null means people see symmetry as non-random beyond what the model's periodicity penalty captures (below null: the model over-penalises).
def test_statistic(df):
    a = df["sequence_a"].to_numpy(); b = df["sequence_b"].to_numpy()
    u = pd.unique(np.concatenate([a, b]))
    tr = str.maketrans("HT", "TH")
    sym = {s: float(s == s[::-1] or s == s[::-1].translate(tr)) for s in u}
    sa = df["sequence_a"].map(sym).to_numpy(); sb = df["sequence_b"].map(sym).to_numpy()
    m = sa != sb
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.where(sa[m] == 0, c, 1 - c).mean())

# name: starts_with_heads_preference
# description: Among pairs whose first flips differ, the rate of choosing the sequence that starts with H; observed above null means people favour H-first sequences more than the model's overall heads-share term implies (below null: the reverse).
def test_statistic(df):
    fa = df["sequence_a"].str[0].to_numpy(); fb = df["sequence_b"].str[0].to_numpy()
    m = fa != fb
    if m.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.where(fa[m] == "H", c, 1 - c).mean())
